insert into public.categories (slug, name, description, pattern_key, sort_order) values
  ('polished-tiles', 'Polished Tiles', 'High-gloss polished floor tiles in a wide range of marble and stone looks.', 'marble', 1),
  ('rustic-tiles', 'Rustic Tiles', 'Textured rustic and anti-slip floor tiles for floors that work hard.', 'slate', 2),
  ('wall-tiles', 'Wall Tiles', 'Glazed wall tiles for kitchens, bathrooms and feature walls.', 'zellige', 3),
  ('floor-tiles', 'Floor Tiles', 'More floor tiles: wood-effect, matt and everyday ranges.', 'cement', 4),
  ('toilets-basins', 'Toilets & Basins', 'Toilets, tanks, seats, basins and pedestals.', 'sanitary', 5),
  ('taps-showers', 'Taps & Showers', 'Basin and kitchen taps, showers, mixers and sinks.', 'tap', 6),
  ('mirrors-cabinets', 'Mirrors & Cabinets', 'Bathroom mirrors, smart mirrors and cabinets.', 'mirror', 7),
  ('doors', 'Doors', 'Security, bathroom and wooden doors.', 'door', 8),
  ('tile-accessories', 'Tile Accessories', 'Spacers, grout, strips and finishing products.', 'accessory', 9),
  ('paint-tools', 'Paint & Tools', 'Paint, brushes, rollers and decorating tools.', 'paint', 10),
  ('hardware', 'Hardware', 'Locks, keys, screws, hinges, handles and fittings.', 'hardware', 11)
on conflict (slug) do update set name = excluded.name, description = excluded.description, pattern_key = excluded.pattern_key, sort_order = excluded.sort_order;

